static bool lowercase_hex_sha256(const char *value) {
    uint64_t i;
    if (value == NULL || strlen(value) != 64u) return false;
    for (i = 0u; i < 64u; ++i) {
        const char c = value[i];
        if (!((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f'))) return false;
    }
    return true;
}

static bool lowercase_hex_commit(const char *value) {
    uint64_t i;
    if (value == NULL || strlen(value) != 40u) return false;
    for (i = 0u; i < 40u; ++i) {
        const char c = value[i];
        if (!((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f'))) return false;
    }
    return true;
}

